-- Redes de oposición mezcladas con igualdad (Luciano et al., 2009), revisadas por el usuario el 2026-11-25: 8 grupos × 4 redes
-- (contrario+contrario, contrario+igual, igual+contrario, igual+igual), opciones por clase sin respuestas dobles, combinatorio
-- «¿lo mismo o lo contrario?», transformación por la red y paso no arbitrario de los tres vasos.
begin;
delete from estimulos_rft_base where clase_base_id in (select id from clases_rft_base where programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Oposición en Redes Combinatorias'));
delete from clases_rft_base where programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Oposición en Redes Combinatorias');
with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, orden, consignas, respuestas_esperadas, opciones_por_fase)
  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Oposición en Redes Combinatorias'), 'Clase 1', 'Grupo 1', 1, $j${"entrenamiento:A→B": "El botón Tok hace lo contrario que el botón Mif. ¿Qué botón hace lo contrario que el botón Mif?", "entrenamiento:B→C": "El botón Tok hace lo contrario que el botón Dax. ¿Qué botón hace lo contrario que el botón Tok?", "test_mutuo:B→A": "El botón Tok hace lo contrario que el botón Mif. ¿Qué botón hace lo contrario que el botón Tok?", "test_combinatorio:A→C": "El botón Tok hace lo contrario que el botón Mif. El botón Tok hace lo contrario que el botón Dax. ¿El botón Dax hace lo mismo o lo contrario que el botón Mif?", "test_combinatorio:C→A": "El botón Tok hace lo contrario que el botón Mif. El botón Tok hace lo contrario que el botón Dax. ¿El botón Mif hace lo mismo o lo contrario que el botón Dax?", "transformacion_funciones:A→C": "El botón Mif enciende la música. El botón Tok hace lo contrario que el botón Mif. El botón Tok hace lo contrario que el botón Dax. ¿Qué hace el botón Dax: enciende la música o apaga la música?"}$j$::jsonb, $j${"entrenamiento:A→B": "El botón Tok", "entrenamiento:B→C": "El botón Dax", "test_mutuo:B→A": "El botón Mif", "test_combinatorio:A→C": "Lo mismo", "test_combinatorio:C→A": "Lo mismo", "transformacion_funciones:A→C": "Enciende la música"}$j$::jsonb, $j${"entrenamiento:A→B": ["El botón Gufi", "El botón Mif", "El botón Tok"], "entrenamiento:B→C": ["El botón Dax", "El botón Pifo", "El botón Tok"], "test_mutuo:B→A": ["El botón Daku", "El botón Mif", "El botón Tok"], "test_combinatorio:A→C": ["Lo mismo", "Lo contrario"], "test_combinatorio:C→A": ["Lo mismo", "Lo contrario"], "transformacion_funciones:A→C": ["Enciende la música", "Apaga la música"]}$j$::jsonb) returning id)
insert into estimulos_rft_base (clase_base_id, etiqueta, posicion, nombre, concepto_imagen)
select id, 'A1', 'A', $j$El botón Mif$j$, null from nueva union all select id, 'B1', 'B', $j$El botón Tok$j$, null from nueva union all select id, 'C1', 'C', $j$El botón Dax$j$, null from nueva;
with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, orden, consignas, respuestas_esperadas, opciones_por_fase)
  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Oposición en Redes Combinatorias'), 'Clase 2', 'Grupo 1', 2, $j${"entrenamiento:A→B": "El botón Rof hace lo contrario que el botón Gufi. ¿Qué botón hace lo contrario que el botón Rof?", "entrenamiento:B→C": "El botón Saro hace lo mismo que el botón Gufi. ¿Qué botón hace lo mismo que el botón Gufi?", "test_mutuo:B→A": "El botón Rof hace lo contrario que el botón Gufi. ¿Qué botón hace lo contrario que el botón Gufi?", "test_combinatorio:A→C": "El botón Rof hace lo contrario que el botón Gufi. El botón Saro hace lo mismo que el botón Gufi. ¿El botón Saro hace lo mismo o lo contrario que el botón Rof?", "test_combinatorio:C→A": "El botón Rof hace lo contrario que el botón Gufi. El botón Saro hace lo mismo que el botón Gufi. ¿El botón Rof hace lo mismo o lo contrario que el botón Saro?", "transformacion_funciones:A→C": "El botón Rof apaga la música. El botón Rof hace lo contrario que el botón Gufi. El botón Saro hace lo mismo que el botón Gufi. ¿Qué hace el botón Saro: enciende la música o apaga la música?"}$j$::jsonb, $j${"entrenamiento:A→B": "El botón Gufi", "entrenamiento:B→C": "El botón Saro", "test_mutuo:B→A": "El botón Rof", "test_combinatorio:A→C": "Lo contrario", "test_combinatorio:C→A": "Lo contrario", "transformacion_funciones:A→C": "Enciende la música"}$j$::jsonb, $j${"entrenamiento:A→B": ["El botón Gufi", "El botón Nako", "El botón Rof"], "entrenamiento:B→C": ["El botón Gufi", "El botón Kiro", "El botón Saro"], "test_mutuo:B→A": ["El botón Gufi", "El botón Mif", "El botón Rof"], "test_combinatorio:A→C": ["Lo mismo", "Lo contrario"], "test_combinatorio:C→A": ["Lo mismo", "Lo contrario"], "transformacion_funciones:A→C": ["Enciende la música", "Apaga la música"]}$j$::jsonb) returning id)
insert into estimulos_rft_base (clase_base_id, etiqueta, posicion, nombre, concepto_imagen)
select id, 'A2', 'A', $j$El botón Rof$j$, null from nueva union all select id, 'B2', 'B', $j$El botón Gufi$j$, null from nueva union all select id, 'C2', 'C', $j$El botón Saro$j$, null from nueva;
with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, orden, consignas, respuestas_esperadas, opciones_por_fase)
  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Oposición en Redes Combinatorias'), 'Clase 3', 'Grupo 1', 3, $j${"entrenamiento:A→B": "El botón Nako hace lo mismo que el botón Lebu. ¿Qué botón hace lo mismo que el botón Lebu?", "entrenamiento:B→C": "El botón Nako hace lo contrario que el botón Pifo. ¿Qué botón hace lo contrario que el botón Nako?", "test_mutuo:B→A": "El botón Nako hace lo mismo que el botón Lebu. ¿Qué botón hace lo mismo que el botón Nako?", "test_combinatorio:A→C": "El botón Nako hace lo contrario que el botón Pifo. El botón Nako hace lo mismo que el botón Lebu. ¿El botón Pifo hace lo mismo o lo contrario que el botón Lebu?", "test_combinatorio:C→A": "El botón Nako hace lo contrario que el botón Pifo. El botón Nako hace lo mismo que el botón Lebu. ¿El botón Lebu hace lo mismo o lo contrario que el botón Pifo?", "transformacion_funciones:A→C": "El botón Lebu enciende la música. El botón Nako hace lo contrario que el botón Pifo. El botón Nako hace lo mismo que el botón Lebu. ¿Qué hace el botón Pifo: enciende la música o apaga la música?"}$j$::jsonb, $j${"entrenamiento:A→B": "El botón Nako", "entrenamiento:B→C": "El botón Pifo", "test_mutuo:B→A": "El botón Lebu", "test_combinatorio:A→C": "Lo contrario", "test_combinatorio:C→A": "Lo contrario", "transformacion_funciones:A→C": "Apaga la música"}$j$::jsonb, $j${"entrenamiento:A→B": ["El botón Lebu", "El botón Nako", "El botón Tefa"], "entrenamiento:B→C": ["El botón Dax", "El botón Nako", "El botón Pifo"], "test_mutuo:B→A": ["El botón Lebu", "El botón Nako", "El botón Rof"], "test_combinatorio:A→C": ["Lo mismo", "Lo contrario"], "test_combinatorio:C→A": ["Lo mismo", "Lo contrario"], "transformacion_funciones:A→C": ["Enciende la música", "Apaga la música"]}$j$::jsonb) returning id)
