  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Oposición en Redes Combinatorias'), 'Clase 4', 'Grupo 1', 4, $j${"entrenamiento:A→B": "El botón Daku hace lo mismo que el botón Tefa. ¿Qué botón hace lo mismo que el botón Daku?", "entrenamiento:B→C": "El botón Kiro hace lo mismo que el botón Tefa. ¿Qué botón hace lo mismo que el botón Tefa?", "test_mutuo:B→A": "El botón Daku hace lo mismo que el botón Tefa. ¿Qué botón hace lo mismo que el botón Tefa?", "test_combinatorio:A→C": "El botón Kiro hace lo mismo que el botón Tefa. El botón Daku hace lo mismo que el botón Tefa. ¿El botón Kiro hace lo mismo o lo contrario que el botón Daku?", "test_combinatorio:C→A": "El botón Kiro hace lo mismo que el botón Tefa. El botón Daku hace lo mismo que el botón Tefa. ¿El botón Daku hace lo mismo o lo contrario que el botón Kiro?", "transformacion_funciones:A→C": "El botón Daku apaga la música. El botón Kiro hace lo mismo que el botón Tefa. El botón Daku hace lo mismo que el botón Tefa. ¿Qué hace el botón Kiro: enciende la música o apaga la música?"}$j$::jsonb, $j${"entrenamiento:A→B": "El botón Tefa", "entrenamiento:B→C": "El botón Kiro", "test_mutuo:B→A": "El botón Daku", "test_combinatorio:A→C": "Lo mismo", "test_combinatorio:C→A": "Lo mismo", "transformacion_funciones:A→C": "Apaga la música"}$j$::jsonb, $j${"entrenamiento:A→B": ["El botón Daku", "El botón Tefa", "El botón Tok"], "entrenamiento:B→C": ["El botón Kiro", "El botón Saro", "El botón Tefa"], "test_mutuo:B→A": ["El botón Daku", "El botón Lebu", "El botón Tefa"], "test_combinatorio:A→C": ["Lo mismo", "Lo contrario"], "test_combinatorio:C→A": ["Lo mismo", "Lo contrario"], "transformacion_funciones:A→C": ["Enciende la música", "Apaga la música"]}$j$::jsonb) returning id)
