  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Oposición en Redes Combinatorias'), 'Clase 5', 'Grupo 2', 5, $j${"entrenamiento:A→B": "La palanca Bema hace lo contrario que la palanca Fuko. ¿Qué palanca hace lo contrario que la palanca Bema?", "entrenamiento:B→C": "La palanca Rafu hace lo contrario que la palanca Fuko. ¿Qué palanca hace lo contrario que la palanca Fuko?", "test_mutuo:B→A": "La palanca Bema hace lo contrario que la palanca Fuko. ¿Qué palanca hace lo contrario que la palanca Fuko?", "test_combinatorio:A→C": "La palanca Rafu hace lo contrario que la palanca Fuko. La palanca Bema hace lo contrario que la palanca Fuko. ¿La palanca Rafu hace lo mismo o lo contrario que la palanca Bema?", "test_combinatorio:C→A": "La palanca Rafu hace lo contrario que la palanca Fuko. La palanca Bema hace lo contrario que la palanca Fuko. ¿La palanca Bema hace lo mismo o lo contrario que la palanca Rafu?", "transformacion_funciones:A→C": "La palanca Bema sube la barrera. La palanca Rafu hace lo contrario que la palanca Fuko. La palanca Bema hace lo contrario que la palanca Fuko. ¿Qué hace la palanca Rafu: sube la barrera o baja la barrera?"}$j$::jsonb, $j${"entrenamiento:A→B": "La palanca Fuko", "entrenamiento:B→C": "La palanca Rafu", "test_mutuo:B→A": "La palanca Bema", "test_combinatorio:A→C": "Lo mismo", "test_combinatorio:C→A": "Lo mismo", "transformacion_funciones:A→C": "Sube la barrera"}$j$::jsonb, $j${"entrenamiento:A→B": ["La palanca Bema", "La palanca Fuko", "La palanca Mepa"], "entrenamiento:B→C": ["La palanca Fuko", "La palanca Kuda", "La palanca Rafu"], "test_mutuo:B→A": ["La palanca Bema", "La palanca Bofi", "La palanca Fuko"], "test_combinatorio:A→C": ["Lo mismo", "Lo contrario"], "test_combinatorio:C→A": ["Lo mismo", "Lo contrario"], "transformacion_funciones:A→C": ["Sube la barrera", "Baja la barrera"]}$j$::jsonb) returning id)
